python
def chainTurntableFirstQualifyingSlip(head, k):
    a=head
    out=[]
    previous=None
    node=a
    while node:
        next_node=node.next
        node.next=previous
        previous=node
        node=next_node
    node=previous
    while node:
        out.append(node.val)
        node=node.next
    return next((x for x in out if x>=k),-1)


